<script>window.kEducationTourCopy=<?=json_encode($tourCopy,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const localizedNext=document.getElementById('tourNext'),localizedSteps=[...document.querySelectorAll('.tour-step')];new MutationObserver(()=>{const copy=window.kEducationTourCopy,wanted=localizedSteps.at(-1).classList.contains('active')?copy.start:copy.next;if(localizedNext.textContent!==wanted)localizedNext.textContent=wanted}).observe(localizedNext,{childList:true,characterData:true,subtree:true});</script>
<script>(()=>{const steps=[...document.querySelectorAll('.tour-step')],voiceButton=document.getElementById('tourVoice'),nextButton=document.getElementById('tourNext'),backButton=document.getElementById('tourBack'),language=<?=json_encode($tourLanguage==='si'?'si-LK':'en-GB')?>,recordings=<?=$tourLanguage==='si'?json_encode($tourRecordings,JSON_UNESCAPED_SLASHES):'[]'?>,recordedOnly=<?=json_encode($tourLanguage==='si')?>;let voiceOn=true,timer=null,run=0,currentAudio=null;const activeIndex=()=>steps.findIndex(step=>step.classList.contains('active'));const stopVoice=()=>{clearTimeout(timer);window.speechSynthesis?.cancel();if(currentAudio){currentAudio.pause();currentAudio.removeAttribute('src');currentAudio.load();currentAudio=null}};const advance=(index,token)=>{if(token===run&&index>=0&&index<steps.length-1&&activeIndex()===index)setTimeout(()=>{if(token===run)nextButton.click()},700)};const speak=(index,token)=>{if(recordedOnly)return;const text=(steps[index].querySelector('h2')?.textContent||'')+'. '+(steps[index].querySelector('p')?.textContent||'');const fallback=Math.min(18000,Math.max(6500,text.length*65));if(!('speechSynthesis'in window)){if(index<steps.length-1)timer=setTimeout(()=>advance(index,token),fallback);return}const speech=new SpeechSynthesisUtterance(text);speech.lang=language;speech.rate=.92;speech.pitch=1.03;speech.onend=()=>advance(index,token);speech.onerror=()=>{if(index<steps.length-1)timer=setTimeout(()=>advance(index,token),fallback)};speechSynthesis.speak(speech)};const narrate=()=>{stopVoice();const token=++run,index=activeIndex();if(index<0||!voiceOn)return;const source=recordings[index];if(!source){speak(index,token);return}const audio=currentAudio=new Audio(source);audio.preload='auto';audio.onended=()=>{currentAudio=null;advance(index,token)};audio.onerror=()=>{currentAudio=null;if(token===run)speak(index,token)};audio.play().catch(()=>{currentAudio=null;if(token===run)speak(index,token)})};let debounce;new MutationObserver(()=>{clearTimeout(debounce);debounce=setTimeout(narrate,450)}).observe(document.getElementById('studentTour'),{attributes:true,subtree:true,attributeFilter:['class']});voiceButton.addEventListener('click',()=>{voiceOn=!voiceOn;voiceButton.setAttribute('aria-pressed',String(voiceOn));voiceButton.textContent=voiceOn?window.kEducationTourCopy.sound:window.kEducationTourCopy.muted;if(voiceOn)narrate();else{run++;stopVoice()}});backButton.addEventListener('click',()=>{run++;stopVoice()});nextButton.addEventListener('click',()=>{run++;stopVoice()});document.getElementById('tourSkip').addEventListener('click',()=>{run++;stopVoice()});setTimeout(narrate,800)})();</script>
<script>document.body.style.overflow='hidden';(()=>{const overlay=document.getElementById('studentTour'),box=overlay.querySelector('.tour-box'),steps=[...overlay.querySelectorAll('.tour-step')],dots=[...overlay.querySelectorAll('.tour-dot')],emoji=document.getElementById('tourEmoji'),progress=document.getElementById('tourProgress'),back=document.getElementById('tourBack'),next=document.getElementById('tourNext'),pointer=document.createElement('span');pointer.className='tour-pointer';pointer.textContent='👇';document.body.appendChild(pointer);let current=0,target=null;const place=()=>{if(!target)return;const r=target.getBoundingClientRect(),gap=14,bw=Math.min(390,innerWidth-24),bh=box.offsetHeight;let left=Math.max(12,Math.min(innerWidth-bw-12,r.left+r.width/2-bw/2)),top=r.bottom+gap;if(top+bh>innerHeight-10)top=Math.max(10,r.top-bh-gap);box.style.left=left+'px';box.style.top=top+'px';pointer.style.left=Math.max(8,Math.min(innerWidth-50,r.left+r.width/2-20))+'px';pointer.style.top=Math.max(5,r.top-49)+'px'};const show=()=>{target?.classList.remove('tour-target');steps.forEach((x,i)=>x.classList.toggle('active',i===current));dots.forEach((x,i)=>x.classList.toggle('active',i===current));emoji.textContent=steps[current].dataset.emoji;progress.style.width=((current+1)/steps.length*100)+'%';back.hidden=current===0;next.textContent=current===steps.length-1?'Explore subjects →':'Next →';const key=steps[current].dataset.target;target=key?document.querySelector('[data-tour="'+key+'"]'):null;overlay.classList.toggle('coach',!!target);pointer.hidden=!target;if(target){document.body.style.overflow='auto';target.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>{target.classList.add('tour-target');place()},380)}else{document.body.style.overflow='hidden';box.removeAttribute('style')}};const close=()=>{target?.classList.remove('tour-target');pointer.remove();document.body.style.overflow='';overlay.remove();history.replaceState({},'',location.pathname)};next.onclick=()=>{if(current===steps.length-1){location.href='subjects.php';return}current++;show()};back.onclick=()=>{current--;show()};document.getElementById('tourSkip').onclick=close;addEventListener('resize',place);addEventListener('keydown',e=>{if(e.key==='Escape')close()});show()})();</script><?php endif;?>
<script>
(()=>{
    const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const finePointer=window.matchMedia('(hover: hover) and (pointer: fine)').matches;
    const cards=[...document.querySelectorAll('.quick-card')];
    cards.forEach((card,index)=>card.style.setProperty('--card-index',index));

    const progressStat=document.querySelector('.stat');
    const progressValue=parseInt(progressStat?.querySelector('strong')?.textContent||'0',10)||0;
    progressStat?.style.setProperty('--progress',progressValue);

    const heroCopy=document.querySelector('#dashboardHero .row > div');
    if(heroCopy){
        const hour=new Date().getHours();
        const message=hour<12?'Good morning — ready to learn?':hour<17?'Good afternoon — keep growing!':'Good evening — one more learning win!';
        const greeting=document.createElement('div');
        greeting.className='dynamic-greeting';
        greeting.textContent=message;
        heroCopy.appendChild(greeting);
    }

    if(!reduceMotion){
        document.querySelectorAll('.stat strong').forEach(value=>{
            const original=value.textContent.trim();
            const target=parseInt(original.replace(/[^0-9]/g,''),10);
            if(!Number.isFinite(target))return;
            const suffix=original.includes('%')?'%':'';
            const started=performance.now(),duration=700;
            const tick=now=>{const amount=Math.round(target*Math.min(1,(now-started)/duration));value.textContent=amount+suffix;if(now-started<duration)requestAnimationFrame(tick)};
            requestAnimationFrame(tick);
        });
    }

    const toast=document.createElement('div');
    toast.className='dashboard-toast';
    toast.innerHTML='<span>✨</span><div>Your learning space is ready. Pick a card and begin!</div>';
    document.body.appendChild(toast);
    window.setTimeout(()=>toast.classList.add('show'),650);
    window.setTimeout(()=>toast.classList.remove('show'),4400);

    if(reduceMotion||!finePointer)return;

    cards.forEach(card=>{
        const reset=()=>{card.style.transform='';card.style.removeProperty('--glow-x');card.style.removeProperty('--glow-y')};
        card.addEventListener('pointermove',event=>{
            const rect=card.getBoundingClientRect();
            const x=(event.clientX-rect.left)/rect.width;
            const y=(event.clientY-rect.top)/rect.height;
            card.style.setProperty('--glow-x',(x*100)+'%');
            card.style.setProperty('--glow-y',(y*100)+'%');
            card.style.transform=`rotateX(${(0.5-y)*9}deg) rotateY(${(x-0.5)*11}deg) translateY(-7px)`;
        });
        card.addEventListener('pointerleave',reset);
        card.addEventListener('blur',reset,true);
    });

    const hero=document.getElementById('dashboardHero');
    const orbit=hero?.querySelector('.hero-orbit');
    hero?.addEventListener('pointermove',event=>{
        const rect=hero.getBoundingClientRect();
        const x=(event.clientX-rect.left)/rect.width-.5;
        const y=(event.clientY-rect.top)/rect.height-.5;
        if(orbit)orbit.style.transform=`translate3d(${x*18}px,${y*14}px,30px) rotateY(${x*8}deg)`;
    });
    hero?.addEventListener('pointerleave',()=>{if(orbit)orbit.style.transform='translateZ(30px)'});
})();
</script>
